typedef unsigned int nslSoundId;
struct nslSound { char pad[28]; int dampenCount; char tail[56]; };
struct nslSystem { char pad0[0xC040]; nslSound soundSlots[256]; char pad1[0x400C]; int initialized; char pad2[44]; bool on; };
extern nslSystem nsl;
extern void _nslCheckSoundIdValidity(nslSoundId checkId);
#define NSL_SLOT_MASK 0x000003FF
#define NSL_GET_SLOT_FROM_ID( x ) ( x&NSL_SLOT_MASK )
#define ASSERT_SOUND_ID_VALID(checkId) _nslCheckSoundIdValidity(checkId)

void nslDampenGuardSound( nslSoundId soundToGuard )
{
  if (!nsl.on) return;
// not needed?   ASSERT_SOURCE_ID_VALID(nsl.soundSlots[NSL_GET_SLOT_FROM_ID(soundToGuard)].mySource);

  ASSERT_SOUND_ID_VALID(soundToGuard);

  if (nsl.soundSlots[NSL_GET_SLOT_FROM_ID(soundToGuard)].dampenCount <= 0)
    nsl.soundSlots[NSL_GET_SLOT_FROM_ID(soundToGuard)].dampenCount = -1;
}
